// ── Rental Genie payment-inbox parser (n8n Code node body lives in parseItem) ──
// Accepts a Postmark inbound payload. Returns one of:
//   { route: 0, ...parsed }        rule-parsed payment  -> ingest
//   { route: 1, token, text, ... } unknown format       -> AI extraction
//   { route: 2, token, verifyUrl } Gmail forwarding verification
//   { route: 3, reason }           skip (marketing, outgoing, not a payment)

function header(payload, name) {
  var list = payload.Headers || [];
  var lower = name.toLowerCase();
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].Name || '').toLowerCase() === lower) return String(list[i].Value || '');
  }
  return '';
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|td|th|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#36;/g, '$')
    .replace(/[ \t]+/g, ' ');
}

function toISODate(s) {
  if (!s) return null;
  var d = new Date(String(s).replace(/\./g, '') + ' 12:00');
  if (isNaN(d)) return null;
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function money(s) {
  if (s == null) return null;
  var n = Number(String(s).replace(/[,\s$]/g, ''));
  return isFinite(n) && n > 0 ? n : null;
}

function dkimPassFor(payload, domain) {
  var ar = (header(payload, 'Authentication-Results') + ' ' + header(payload, 'ARC-Authentication-Results')).toLowerCase();
  return ar.indexOf('dkim=pass') >= 0 && ar.indexOf(domain) >= 0;
}

function inboxToken(payload) {
  if (payload.MailboxHash) return String(payload.MailboxHash).toLowerCase();
  var to = String(payload.OriginalRecipient || payload.To || '');
  var m = to.match(/rent-([a-z0-9]{6,32})@/i);
  return m ? m[1].toLowerCase() : null;
}

function parseItem(payload) {
  var from = String((payload.FromFull && payload.FromFull.Email) || payload.From || '').toLowerCase();
  var subject = String(payload.Subject || '');
  var text = String(payload.TextBody || '');
  if (text.replace(/[\s|]/g, '').length < 20) text = htmlToText(payload.HtmlBody);
  var flat = text.replace(/\s+/g, ' ');
  var token = inboxToken(payload);
  var messageId = header(payload, 'Message-ID') || payload.MessageID || null;

  if (!token) return { route: 3, reason: 'no inbox token' };

  // Gmail asks the new forwarding address to confirm it
  if (from.indexOf('forwarding-noreply@google.com') >= 0) {
    var link = flat.match(/https:\/\/mail(?:-settings)?\.google\.com\/mail\/[^\s)"'<>]+/i);
    return link ? { route: 2, token: token, verifyUrl: link[0] } : { route: 3, reason: 'verification email without link' };
  }

  // Chase: "You received money with Zelle®"
  if (from.indexOf('chase.com') >= 0 && /received money with zelle/i.test(subject)) {
    var payer = (flat.match(/\|?\s*([A-Za-z0-9 .,'&-]{2,80}?)\s+sent you money/i) || [])[1];
    var amount = money((flat.match(/Amount[\s|:]*\$\s*([\d,]+(?:\.\d{2})?)/i) || [])[1]);
    var date = toISODate((flat.match(/Sent on[\s|:]*([A-Za-z]{3,9}\.? \d{1,2}, \d{4})/i) || [])[1]);
    var txn = (flat.match(/Transaction number[\s|:#]*([A-Za-z0-9]+)/i) || [])[1] || null;
    var memoM = text.match(/Memo[ \t|:]*([^|\n\r]+)/i);
    var memo = memoM ? memoM[1].trim() : null;
    if (payer && amount) {
      return { route: 0, token: token, messageId: messageId, source: 'chase_zelle', method: 'Zelle',
               payer: payer.trim(), amount: amount, date: date, memo: memo, txn: txn,
               subject: subject, body: flat.slice(0, 4000), verified: dkimPassFor(payload, 'chase.com') };
    }
  }

  // Venmo: "Name paid you $X" (only venmo@venmo.com; email.venmo.com is marketing)
  if (from === 'venmo@venmo.com' || /<venmo@venmo\.com>/.test(from)) {
    var vs = subject.match(/^(.+?) paid you \$([\d,]+(?:\.\d{2})?)/i);
    if (!vs) return { route: 3, reason: 'venmo email that is not an incoming payment' };
    var vDate = toISODate((flat.match(/Date[\s|#:]*([A-Za-z]{3,9}\.? \d{1,2}, \d{4})/i) || [])[1]);
    var vTxn = (flat.match(/Transaction ID[\s|#:]*(\d+)/i) || [])[1] || null;
    var vMemoM = flat.match(/paid you \$\s*[\d,]+\s*\.?\s*\d{0,2}\s+((?:(?!paid you).)*?)\s+See transaction/i);
    return { route: 0, token: token, messageId: messageId, source: 'venmo', method: 'Venmo',
             payer: vs[1].trim(), amount: money(vs[2]), date: vDate, memo: vMemoM ? vMemoM[1].trim() : null,
             txn: vTxn, subject: subject, body: flat.slice(0, 4000), verified: dkimPassFor(payload, 'venmo.com') };
  }
  if (from.indexOf('venmo.com') >= 0) return { route: 3, reason: 'venmo marketing' };

  // Anything else: let the AI step decide whether it is an incoming payment
  return { route: 1, token: token, messageId: messageId, from: from, subject: subject,
           text: flat.slice(0, 6000), verified: false };
}

// Webhook v2 puts the Postmark payload under json.body
return $input.all().map(function (it) {
  var payload = it.json.body || it.json;
  return { json: parseItem(payload) };
});

