// Turn Claude's JSON reply back into the same shape the rule parsers produce.
// Drops anything Claude says is not an incoming payment.
var out = [];
var items = $input.all();
for (var i = 0; i < items.length; i++) {
  var src = $('Parse alert').itemMatching(i).json;
  var resp = items[i].json || {};
  var text = (resp.content && resp.content[0] && resp.content[0].text) || '';
  var data = null;
  try { data = JSON.parse(text.replace(/```json|```/g, '').trim()); } catch (e) { data = null; }
  if (!data || !data.is_incoming_payment || !data.amount || !data.payer) continue;
  out.push({ json: {
    route: 0, token: src.token, messageId: src.messageId, source: 'ai',
    method: data.method || 'Other', payer: data.payer, amount: Number(data.amount),
    date: data.date || null, memo: data.memo || null, txn: data.transaction_ref || null,
    subject: src.subject, body: src.text, verified: false
  } });
}
return out;
